function transform(body, args) {
  const rate = body.rates[args.to];
  return {
    amount: args.amount,
    from: args.from,
    to: args.to,
    rate: rate,
    converted: args.amount * rate,
    date: body.date
  };
}

function transform(body, args) {
  return body.map(item => ({
    date: item.date,
    name: item.name
  }));
}

function transform(body, args) {
  return {
    elevation_m: Array.isArray(body.elevation) ? body.elevation[0] : body.elevation
  };
}

function transform(body, args) {
  return {
    sunrise_utc: body.results.sunrise,
    sunset_utc: body.results.sunset,
    day_length_s: body.results.day_length
  };
}
